{
  "segment_function": "argument",
  "claims": [
    {
      "claim": "Locke grounded private property in the body, treating labor as a world-appropriating activity rooted in the ultimate privacy of the human person.",
      "claim_type": "author_position",
      "supporting_excerpt": "Locke founded private property on the most privately owned thing there is, “the property [of man] in his own person,” that is, in his own body.",
      "support_kind": "direct",
      "qualifications": [
        "applies specifically to Locke's philosophical justification of appropriation"
      ],
      "confidence": 1
    },
    {
      "claim": "Hedonism and the pursuit of an absent of pain represent the most radical forms of a non-political, totally private way of life centered on bodily sensations.",
      "claim_type": "author_position",
      "supporting_excerpt": "Hedonism, the doctrine that only bodily sensations are real, is but the most radical form of a non-political, totally private way of life, the true fulfilment of Epicurus’ lathe biōsas kai mē politeuesthai (“live in hiding and do not care about the world”).",
      "support_kind": "direct",
      "qualifications": [
        "linked to consistent sensualism and the historical tradition of Epicurean and Stoic withdrawal"
      ],
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "Hedonism",
      "definition": "The doctrine that only bodily sensations are real, serving as the most radical form of a non-political, totally private way of life."
    }
  ],
  "distinctions": [
    {
      "item_a": "privacy of appropriation",
      "item_b": "privacy of property",
      "distinction": "Locke's argument for the privacy of appropriation rests on bodily activity, which is distinguished from the very different argument for the privacy of property."
    }
  ],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "Locke's derivation of private property from the body",
    "The connection between bodily life, labor, and the modern growth of wealth",
    "The characterization of hedonism and bodily pain as the basis for a totally private, non-political life"
  ]
}

